while true; do
  status=$(curl -s -H "Authorization: token $GH_TOKEN" -H "Accept: application/vnd.github+json" \
    "https://api.github.com/repos/missingbulb/ClaudiniteCanary/commits/4fad69bc15c308a9c0ef114fa8265881c410e473/check-runs" \
    | node -e '
      let d="";
      process.stdin.on("data", c => d += c);
      process.stdin.on("end", () => {
        const j = JSON.parse(d);
        for (const r of j.check_runs) {
          console.log(`${r.name}: status=${r.status} conclusion=${r.conclusion}`);
        }
      });
    ')
  echo "$status"
  if ! echo "$status" | grep -q "status=in_progress\|status=queued"; then
    echo "CONCLUDED"
    break
  fi
  sleep 20
done

